def multiset_ops(ops):
    counts = {}
    out = []
    for op in ops:
        name, x = op
        if name == 'add':
            counts[x] = counts.get(x, 0) + 1
        elif name == 'remove':
            if counts.get(x, 0) > 0:
                counts[x] -= 1
                out.append(True)
            else:
                out.append(False)
        else:
            out.append(counts.get(x, 0))
    return out
